"""Retrieval and generation metrics."""from typing import List, Dict, Optionalimport ollama# ---------- retrieval ----------def rank_of_gold(retrieved_ids: List[str], gold_ids: List[str]) -> Optional[int]:    """1-indexed rank of the highest-ranked gold chunk, or None."""    ranks = [i + 1 for i, rid in enumerate(retrieved_ids) if rid in gold_ids]    return min(ranks) if ranks else Nonedef recall_at_k(rank: Optional[int], k: int) -> int:    return 1 if rank is not None and rank <= k else 0def reciprocal_rank(rank: Optional[int]) -> float:    return 1.0 / rank if rank is not None else 0.0# ---------- generation ----------JUDGE_PROMPT = """You are evaluating whether an ANSWER is fully supported by the CONTEXT.Rules:- Every factual claim in the ANSWER must be traceable to the CONTEXT.- Outside knowledge, even if true, counts as unsupported.- Ignore citation markers like [1] when judging content.Reply with exactly one line in this format:VERDICT: SUPPORTED | PARTIAL | UNSUPPORTEDThen one sentence of justification."""def judge_faithfulness(answer: str, context: str,                       model: str = "llama3.1:8b") -> Dict:    """LLM-as-judge faithfulness check. Imperfect and correlated with the generator."""    resp = ollama.chat(        model=model,        messages=[            {"role": "system", "content": JUDGE_PROMPT},            {"role": "user",             "content": f"CONTEXT:\n{context}\n\nANSWER:\n{answer}"},        ],        options={"temperature": 0.0},    )    text = resp["message"]["content"].strip()    verdict = "UNPARSEABLE"    for v in ("SUPPORTED", "PARTIAL", "UNSUPPORTED"):        if f"VERDICT: {v}" in text.upper():            verdict = v            break    score = {"SUPPORTED": 1.0, "PARTIAL": 0.5,             "UNSUPPORTED": 0.0, "UNPARSEABLE": 0.0}[verdict]    return {"verdict": verdict, "score": score, "raw": text}def score_abstention(abstained: bool, question_type: str) -> Optional[int]:    """    Correct behaviour depends on the question type.    Returns None for distractors, where either behaviour can be defensible.    """    if question_type == "unanswerable":        return 1 if abstained else 0    if question_type == "answerable":        return 0 if abstained else 1   # abstaining on an answerable question is a failure    return None